#!/usr/bin/env bash
# Alex share server installer for Ubuntu 20.04+.
#   sudo bash install.sh                 -> HTTPS on <your-ip>.sslip.io
#   sudo DOMAIN=share.example.com bash install.sh   -> your own domain (DNS A record first)
# Safe to re-run (upgrades the server, keeps the access token and stored files).
set -euo pipefail

[ "$(id -u)" -eq 0 ] || { echo "Chạy bằng root: sudo bash install.sh"; exit 1; }
command -v apt-get >/dev/null || { echo "Script này dành cho Ubuntu/Debian"; exit 1; }

echo "==> Kiểm tra cổng 80/443"
busy=$(ss -ltnpH '( sport = :80 or sport = :443 )' 2>/dev/null | grep -v caddy || true)
if [ -n "$busy" ]; then
  echo "Cổng 80/443 đang được chương trình khác dùng:"; echo "$busy"
  echo "Dừng lại để không ảnh hưởng dịch vụ đang chạy. Hãy giải phóng cổng hoặc cấu hình reverse proxy tới Alex thủ công."
  exit 1
fi

# 127.0.0.1:8080 is the default, but skip it when another program already holds it.
pick_bind() {
  if [ -f /etc/alex-share.env ]; then
    local b p holders
    b=$(grep '^ALEX_BIND=' /etc/alex-share.env | cut -d= -f2-)
    p="${b##*:}"
    holders=$(ss -ltnpH "sport = :$p" 2>/dev/null || true)
    if [ -n "$b" ] && { [ -z "$holders" ] || echo "$holders" | grep -q 'alex_share.py'; }; then
      printf '%s\n' "$b"
      return
    fi
    echo "Cổng cũ $b đang bị chương trình khác dùng, chọn cổng nội bộ khác." >&2
  fi
  local p
  for p in 8080 8095 8096 8097 8108 8118 8128; do
    if [ -z "$(ss -ltnH "sport = :$p" 2>/dev/null || true)" ]; then
      printf '127.0.0.1:%s\n' "$p"
      return
    fi
  done
  echo "Không tìm được cổng nội bộ trống cho Alex." >&2
  exit 1
}
BIND_ADDR=$(pick_bind)
echo "==> Alex lắng nghe $BIND_ADDR"

echo "==> Cài gói cần thiết"
export DEBIAN_FRONTEND=noninteractive
apt-get update -qq
apt-get install -y -qq python3 curl ca-certificates gnupg debian-keyring debian-archive-keyring apt-transport-https >/dev/null
if ! command -v caddy >/dev/null; then
  echo "==> Cài Caddy (HTTPS tự động)"
  curl -1sLf 'https://dl.cloudsmith.io/public/caddy/stable/gpg.key' | gpg --dearmor --yes -o /usr/share/keyrings/caddy-stable-archive-keyring.gpg
  curl -1sLf 'https://dl.cloudsmith.io/public/caddy/stable/debian.deb.txt' > /etc/apt/sources.list.d/caddy-stable.list
  apt-get update -qq
  apt-get install -y -qq caddy >/dev/null
fi

echo "==> Cài Alex share server"
id alexshare >/dev/null 2>&1 || useradd --system --home /var/lib/alex-share --shell /usr/sbin/nologin alexshare
install -d -o root -g root -m 755 /opt/alex-share
install -d -o alexshare -g alexshare -m 700 /var/lib/alex-share
echo '' | base64 -d > /opt/alex-share/alex_share.py
echo '' | base64 -d > /opt/alex-share/page.html
chmod 644 /opt/alex-share/*

if [ ! -f /etc/alex-share.env ]; then
  cat > /etc/alex-share.env <<EOF
ALEX_DATA=/var/lib/alex-share
ALEX_BIND=$BIND_ADDR
ALEX_MAX_MB=1024
ALEX_QUOTA_GB=20
ALEX_DEVICE_GB=3
ALEX_TTL_HOURS=24
ALEX_REG_PER_DAY=10
EOF
  chmod 600 /etc/alex-share.env
fi
# v2 uses device accounts; the old shared token is no longer needed
sed -i '/^ALEX_TOKEN=/d' /etc/alex-share.env
grep -q '^ALEX_DEVICE_GB=' /etc/alex-share.env || echo 'ALEX_DEVICE_GB=3' >> /etc/alex-share.env
grep -q '^ALEX_REG_PER_DAY=' /etc/alex-share.env || echo 'ALEX_REG_PER_DAY=10' >> /etc/alex-share.env
BIND_ADDR=$(grep '^ALEX_BIND=' /etc/alex-share.env | cut -d= -f2-)
PORT="${BIND_ADDR##*:}"

cat > /etc/systemd/system/alex-share.service <<'EOF'
[Unit]
Description=Alex share server
After=network-online.target

[Service]
User=alexshare
Group=alexshare
EnvironmentFile=/etc/alex-share.env
ExecStart=/usr/bin/python3 /opt/alex-share/alex_share.py
Restart=always
RestartSec=2
NoNewPrivileges=true
ProtectSystem=strict
ProtectHome=true
PrivateTmp=true
PrivateDevices=true
ReadWritePaths=/var/lib/alex-share
RestrictAddressFamilies=AF_INET AF_INET6 AF_UNIX

[Install]
WantedBy=multi-user.target
EOF
systemctl daemon-reload
systemctl enable --now alex-share >/dev/null
systemctl restart alex-share

if [ -z "${DOMAIN:-}" ]; then
  IP=$(curl -4 -fsS https://api.ipify.org || hostname -I | awk '{print $1}')
  DOMAIN="${IP//./-}.sslip.io"
fi
echo "==> Cấu hình HTTPS cho $DOMAIN"
SITE_BODY=$(cat <<EOF
$DOMAIN {
	request_body {
		max_size 1100MB
	}
	reverse_proxy 127.0.0.1:$PORT {
		flush_interval -1
		transport http {
			read_timeout 30m
			write_timeout 30m
			dial_timeout 10s
		}
	}
}
EOF
)
# A Caddyfile that already imports sites/* must not be rewritten.
if [ -f /etc/caddy/Caddyfile ] && grep -q '/etc/caddy/sites' /etc/caddy/Caddyfile; then
  mkdir -p /etc/caddy/sites
  printf '%s\n' "$SITE_BODY" > /etc/caddy/sites/alex-share.caddy
elif [ ! -f /etc/caddy/Caddyfile ] || grep -q '/usr/share/caddy' /etc/caddy/Caddyfile; then
  printf '%s\n' "$SITE_BODY" > /etc/caddy/alex-share.caddy
  echo 'import /etc/caddy/alex-share.caddy' > /etc/caddy/Caddyfile
else
  printf '%s\n' "$SITE_BODY" > /etc/caddy/alex-share.caddy
  if ! grep -q 'alex-share.caddy' /etc/caddy/Caddyfile; then
    printf '\nimport /etc/caddy/alex-share.caddy\n' >> /etc/caddy/Caddyfile
  fi
fi
caddy validate --config /etc/caddy/Caddyfile --adapter caddyfile >/dev/null
systemctl enable caddy >/dev/null 2>&1 || true
systemctl reload caddy 2>/dev/null || systemctl restart caddy

if command -v ufw >/dev/null && ufw status | grep -q 'Status: active'; then
  ufw allow 80/tcp >/dev/null; ufw allow 443/tcp >/dev/null
fi

echo "==> Chờ chứng chỉ HTTPS"
for i in $(seq 1 30); do
  if curl -fsS "https://$DOMAIN/api/ping" >/dev/null 2>&1; then ok=1; break; fi
  sleep 2
done
echo
if [ "${ok:-}" = 1 ]; then echo "Máy chủ đã chạy."; else echo "Máy chủ đã cài nhưng HTTPS chưa sẵn sàng (kiểm tra cổng 80/443 có mở ở tường lửa nhà cung cấp không)."; fi
echo "----------------------------------------------"
echo " Địa chỉ máy chủ : https://$DOMAIN"
echo "----------------------------------------------"
echo "Nhập địa chỉ này vào Alex (tab Gửi > Qua Internet). Alex tự tạo ID và mật khẩu cho mỗi máy;"
echo "điện thoại kết nối bằng ID + mật khẩu đó trên web Alex."
